def transform(grid):
 g=[r[:] for r in grid]; R=len(g); C=len(g[0]); bars=[]
 for i,row in enumerate(grid):
  xs=[j for j,v in enumerate(row) if v]
  if len(xs)>=3:
   # fill internal zero gaps; maintain separate color runs
   for j in range(min(xs),max(xs)+1):
    if row[j]==0:
     l=max(k for k in xs if k<j); r=min(k for k in xs if k>j)
     g[i][j]=row[l] if j-l<=r-j else row[r]
 bars_by_col={}
 for j in range(C):
  bars_by_col[j]=[(i, row[max(k for k,v in enumerate(row) if v and k<j)] if any(v for v in row[:j]) else row[min(k for k,v in enumerate(row) if v and k>j)]) for i,row in enumerate(grid) if len([v for v in row if v])>=3 and min(k for k,v in enumerate(row) if v)<=j<=max(k for k,v in enumerate(row) if v)]
 cols=[j for j in range(C) if any(grid[i][j] for i in range(R-3,R))]
 for j in cols:
  sources=bars_by_col[j]
  for i in range(R):
   if grid[i][j]: continue
   below=[x for x in sources if x[0]>=i]
   if below: g[i][j]=below[0][1]
   else:
    g[i][j]=next((grid[r][j] for r in range(R-1,-1,-1) if grid[r][j]),0)
 return g
